  if (compact) {
    const dark = resolved === "dark";
    return (
      <Button
        variant="surface"
        size="compact-icon"
        onClick={() => setAppearance(dark ? "light" : "dark")}
        aria-label={`Switch to ${dark ? "light" : "dark"} mode`}
        title={`Switch to ${dark ? "light" : "dark"} mode`}
        className="relative text-foreground"
